let lastPlaceSearch=0;let findingPlace=false;let placeAbort=null;
async function findPlace(){const q=$('search').value.trim();if(!q){$('search').focus();showStatus('输入地名，再点搜索框右侧箭头，可查找未列入索引的地点。');return}if(findingPlace||Date.now()-lastPlaceSearch<1200)return;lastPlaceSearch=Date.now();findingPlace=true;$('places').showModal();$('placeResults').replaceChildren();$('placesStatus').textContent='正在查找「'+q+'」…';placeAbort=new AbortController();const timer=setTimeout(()=>placeAbort.abort(),20000);try{const res=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&accept-language=zh-CN,en&q='+encodeURIComponent(q),{signal:placeAbort.signal});if(!res.ok)throw new Error('Place search unavailable');const data=await res.json();if(!Array.isArray(data))throw new Error('Invalid place response');$('placesStatus').textContent=data.length?'选择一个地点，前往地图查看。':'没有找到该地点。试试当地语言或英文地名。';for(const d of data){const lat=Number(d.lat),lng=Number(d.lon);if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)continue;const b=document.createElement('button');b.className='place-result';b.textContent=d.display_name;b.onclick=()=>{cancelParcelRequest();regionRequest++;selected=null;renderList();$('detail').hidden=true;$('places').close();document.querySelector('.explorer').classList.remove('open');$('mobileToggle').textContent='浏览产区';$('mapTitle').textContent=d.name||q;$('mapSubtitle').textContent='地点定位 · 非产区边界';map?.setView([lat,lng],14);showStatus('已定位此处。点击“查看此处地块”加载附近葡萄园与酒庄。')};$('placeResults').append(b)}}catch{$('placesStatus').textContent='地点搜索暂时不可用，请稍后重试。仍可通过产区索引或移动地图查找。'}finally{clearTimeout(timer);findingPlace=false}}
$('placeSearch').onclick=e=>{e.preventDefault();findPlace()};$('closePlaces').onclick=()=>{$('places').close();placeAbort?.abort()};$('search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();findPlace()}});
